package clusterdata.datatypes;

import java.io.Serializable;

/**
 * Represents a task event from the Google cluster trace.
 *
 * CSV Format:
 * timestamp, missing_info, job_id, task_index, machine_id, event_type, user_name,
 * scheduling_class, priority, cpu_request, memory_request, disk_request, different_machines
 */
public class TaskEvent implements Serializable {
    private static final long serialVersionUID = 1L;

    public long timestamp;           // in microseconds
    public String missingInfo;
    public String jobId;
    public long taskIndex;
    public String machineId;
    public int eventType;            // 0=SUBMIT, 1=SCHEDULE, 2=EVICT, 3=FAIL, 4=FINISH, 5=KILL, 6=LOST, 7=UPDATE_PENDING, 8=UPDATE_RUNNING
    public String userName;
    public int schedulingClass;
    public int priority;
    public double cpuRequest;
    public double memoryRequest;
    public double diskRequest;
    public int differentMachines;

    // Default constructor required for Flink POJO
    public TaskEvent() {
    }

    public TaskEvent(long timestamp, String missingInfo, String jobId, long taskIndex,
                     String machineId, int eventType, String userName, int schedulingClass,
                     int priority, double cpuRequest, double memoryRequest, double diskRequest,
                     int differentMachines) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.userName = userName;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.memoryRequest = memoryRequest;
        this.diskRequest = diskRequest;
        this.differentMachines = differentMachines;
    }

    /**
     * Parse a CSV line into a TaskEvent object.
     * Handles empty fields appropriately.
     */
    public static TaskEvent fromCsv(String line) {
        String[] fields = line.split(",", -1);

        TaskEvent event = new TaskEvent();
        event.timestamp = Long.parseLong(fields[0]);
        event.missingInfo = fields[1];
        event.jobId = fields[2];
        event.taskIndex = fields[3].isEmpty() ? 0 : Long.parseLong(fields[3]);
        event.machineId = fields[4];
        event.eventType = Integer.parseInt(fields[5]);
        event.userName = fields[6];
        event.schedulingClass = Integer.parseInt(fields[7]);
        event.priority = Integer.parseInt(fields[8]);
        event.cpuRequest = Double.parseDouble(fields[9]);
        event.memoryRequest = Double.parseDouble(fields[10]);
        event.diskRequest = Double.parseDouble(fields[11]);
        event.differentMachines = Integer.parseInt(fields[12]);

        return event;
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId='" + jobId + '\'' +
                ", taskIndex=" + taskIndex +
                ", eventType=" + eventType +
                '}';
    }
}

