package clusterdata.datatypes;

import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.util.function.Function;
import java.util.zip.GZIPInputStream;

/**
 * Custom source function to read gzipped CSV files.
 *
 * @param <T> The type of records to produce
 */
public class GzipCsvSource<T> implements SourceFunction<T> {
    private static final long serialVersionUID = 1L;

    private final String filePath;
    private final Function<String, T> parseFunction;
    private volatile boolean isRunning = true;

    public GzipCsvSource(String filePath, Function<String, T> parseFunction) {
        this.filePath = filePath;
        this.parseFunction = parseFunction;
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(
                        new GZIPInputStream(new FileInputStream(filePath))))) {
            String line;
            while (isRunning && (line = reader.readLine()) != null) {
                try {
                    T record = parseFunction.apply(line);
                    ctx.collect(record);
                } catch (Exception e) {
                    // Skip malformed lines
                    System.err.println("Error parsing line: " + line + " - " + e.getMessage());
                }
            }
        }
    }

    @Override
    public void cancel() {
        isRunning = false;
    }
}

